INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1463', N'Thức Tỉnh 2-Đạn Mai Rùa', N'3410,3411,3412,3413,3414,', N'Ném một mai rùa cứng chắc, gây 220% sát thương, chắc chắn bạo kích. 2 đồng đội ngẫu nhiên nhận hiệu quả 20% Giảm Thương (Không có đồng đội sẽ tăng cho bản thân), HP tối đa tăng 20%, duy trì 3 turn', '1', '11398', '20', '138', N'beatA', N'effect085', '1400', '3', '0', '-1', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1464', N'Thức Tỉnh 2-Giáp Gai', N'3415,3416,3417,3418,', N'Vào trạng thái phòng thủ, Hộ Giáp tăng 80%, miễn trừ 90% xác suất bị bạo kích. Bản thân tăng thể tích va chạm, miễn sát thương từ một vài góc độ, khiến toàn phe địch giảm 50% Ma Công, duy trì 3 turn.', '3', '-1', '10', '139', N'beatB', N'', '1400', '6', '0', '-1', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1465', N'Thức Tỉnh 2-Miệt Thị', N'3419,3420,3421,3422,3423,3424,3425,3426,', N'Khi đạt 30 MP sẽ kích hoạt Khiêu Khích, khiến toàn phe địch giảm 50% tấn công Nguyên Tố, thu hút Đạn Pháo của kẻ địch trong bán kính 200 xung quanh, mỗi lần bị trúng Đạn Pháo sẽ phản đòn lên kẻ tấn công sát thương thực bằng (80% Hộ Giáp của bản thân +800 điểm), duy trì 2 turn, cần chờ 3 turn (Có hiệu lực trong PVP).', '3', '-1', '0', '140', N'', N'', '0', '3', '2', '10000', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1466', N'Thức Tỉnh 2-Núi Đè', N'3427,3428,3429,3430,', N'Rùa khổng lồ ép mạnh xuống đất, gây cho tất cả người chơi sát thương bằng (150% ST cơ bản + 300% Hộ Giáp của bản thân), cấm di chuyển, cấm bay, cấm dùng kỹ năng Pet, duy trì 2 turn.', '2', '-1', '30', '142', N'beatC', N'', '1400', '4', '0', '-1', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1467', N'Thức Tỉnh 2-Bật Lại', N'3431,3432,3542,', N'Mỗi lần bị sát thương, sẽ hồi phục 5 điểm MP, đồng thời tăng 10% Ma Kháng và Hộ Giáp, tối đa cộng dồn 4 tầng, duy trì 2 turn, mỗi turn tối đa hồi 15 điểm MP (Miễn dịch thêm phát đạn đầu tiên, chỉ hiệu lực trong PVP). Miễn dịch 1 lần sát thương chí mạng và hồi 30% HP tối đa, mỗi trận tối đa 1 lần.', '3', '-1', '0', '143', N'', N'', '0', '0', '0', '10000', '0', '0');
