INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1499', N'Thức Tỉnh 3-Tư Thế Phòng Thủ', N'3465,', N'Kháng Xuyên Giáp +8%. Xuất Chiêu: Mai Rùa. Trong turn, sau khi khi dùng "PASS", sẽ khởi động Tư Thế Phòng Thủ, sát thương phải chịu -30%, sát thương bạo kích phải chịu -60%, duy trì 2 turn, tăng thêm 2 MP.', '3', '-1', '0', '-1', N'', N'', '0', '0', '0', '10000', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1500', N'Thức Tỉnh 3-Tư Thế Tấn Công', N'3466,', N'Kháng Bỏng +10%. Xuất Chiêu: Thần Tốc. Turn này chắc chắn kích hoạt Thần Tốc, tăng 40% tốc độ tấn công. Trong turn kích hoạt Thần Tốc, thể lực giảm còn 80, duy trì 1 turn, tăng thêm hiệu quả Miễn Kháng, duy trì 2 turn.', '3', '-1', '0', '-1', N'', N'', '0', '0', '0', '10000', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1501', N'Thức Tỉnh 3-Chuyên Gia Võ Thuật', N'3467,', N'Kháng Xuyên Giáp +8%. Mỗi khi Xuất Chiêu, hồi 3 MP, kích hoạt hiệu quả Tuyệt Địa Phản Kích, mỗi mất 1% HP tối đa, sẽ tăng 1.3% sát thương gây ra (Tối đa tăng 80%, duy trì 1 turn).', '3', '-1', '0', '-1', N'', N'', '0', '0', '0', '10000', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1512', N'Thức Tỉnh 3-Đạn Mai Rùa', N'3479,', N'Kháng Bỏng +15%. Ném một mai rùa cứng chắc, gây 220% sát thương, chắc chắn bạo kích. 2 đồng đội ngẫu nhiên nhận hiệu quả 20% Giảm Thương (Không có đồng đội sẽ tăng cho bản thân), HP tối đa tăng 20%, duy trì 3 turn', '3', '-1', '0', '-1', N'', N'', '0', '0', '0', '10000', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1513', N'Thức Tỉnh 3-Giáp Gai', N'3480,', N'Kháng Xuyên Giáp +12%. Vào trạng thái phòng thủ, Hộ Giáp tăng 80%, miễn trừ 90% xác suất bị bạo kích. Bản thân tăng thể tích va chạm, miễn sát thương từ một vài góc độ, khiến toàn phe địch giảm 50% Ma Công, duy trì 3 turn.', '3', '-1', '0', '-1', N'', N'', '0', '0', '0', '10000', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1514', N'Thức Tỉnh 3-Miệt Thị', N'3481,', N'Kháng Xuyên Giáp +12%. Khi đạt 30 MP sẽ kích hoạt Khiêu Khích, khiến toàn phe địch giảm 50% tấn công Nguyên Tố, thu hút Đạn Pháo của kẻ địch trong bán kính 200 xung quanh, mỗi lần bị trúng Đạn Pháo sẽ phản đòn lên kẻ tấn công sát thương thực bằng (80% Hộ Giáp của bản thân +800 điểm), duy trì 2 turn, cần chờ 3 turn (Có hiệu lực trong PVP).', '3', '-1', '0', '-1', N'', N'', '0', '0', '0', '10000', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1515', N'Thức Tỉnh 3-Núi Đè', N'3482,', N'Kháng Bỏng +15%. Rùa khổng lồ ép mạnh xuống đất, gây cho tất cả người chơi sát thương bằng (150% ST cơ bản + 300% Hộ Giáp của bản thân), cấm di chuyển, cấm bay, cấm dùng kỹ năng Pet, duy trì 2 turn.', '3', '-1', '0', '-1', N'', N'', '0', '0', '0', '10000', '0', '0');
INSERT INTO [Pet_Skill_Info] ([ID],[Name],[ElementIDs],[Description],[BallType],[NewBallID],[CostMP],[Pic],[Action],[EffectPic],[Delay],[ColdDown],[GameType],[Probability],[Damage],[DamageCrit])  VALUES ('1516', N'Thức Tỉnh 3-Bật Lại', N'3483,', N'Kháng Bỏng +15%. Mỗi lần bị sát thương, sẽ hồi phục 5 điểm MP, đồng thời tăng 10% Ma Kháng và Hộ Giáp, tối đa cộng dồn 4 tầng, duy trì 2 turn, mỗi turn tối đa hồi 15 điểm MP (Miễn dịch thêm phát đạn đầu tiên, chỉ hiệu lực trong PVP). Miễn dịch 1 lần sát thương chí mạng và hồi 30% HP tối đa, mỗi trận tối đa 1 lần.', '3', '-1', '0', '-1', N'', N'', '0', '0', '0', '10000', '0', '0');
